        io={key:int(value)for key,value in(line.split(':',1)for line in(root/'io').read_text().splitlines())}
        rss=next(int(line.split()[1])*1024 for line in(root/'status').read_text().splitlines()if line.startswith('VmRSS:'))
        inodes=set();sockets=[];network_errors=[]
