class ResourceWindow:
    def __init__(self,nodes):self.nodes=nodes;self.stop=threading.Event();self.samples=[];self.errors=[]
    def capture(self):self.samples.append({'monotonic_s':time.monotonic(),'nodes':{label:sample(pid)for label,pid in list(self.nodes)}})
